package com.example.echowithin.data.repository

import com.example.echowithin.data.model.LoginRequest
import com.example.echowithin.data.network.ApiClient

class AuthRepository {
    private val api = ApiClient.apiService

    suspend fun login(username: String, password: String): Result<Unit> {
        return runCatching {
            val response = api.login(LoginRequest(username = username, password = password))
            if (!response.success) {
                throw IllegalStateException(response.error ?: "Login failed")
            }
        }
    }

    suspend fun logout(): Result<Unit> {
        return runCatching {
            val response = api.logout()
            if (!response.success) {
                throw IllegalStateException(response.error ?: "Logout failed")
            }
        }
    }
}

package com.example.echowithin.data.repository

import com.example.echowithin.data.model.ConfirmRequest
import com.example.echowithin.data.model.LoginRequest
import com.example.echowithin.data.model.LoginResponse
import com.example.echowithin.data.model.RegisterRequest
import com.example.echowithin.data.model.RegisterResponse
import com.example.echowithin.data.network.ApiClient

class AuthRepository(private val api: EchoWithinApiService) {
    suspend fun login(request: LoginRequest): Result<LoginResponse> = runCatching {
        api.login(request)
    }

    suspend fun register(request: RegisterRequest): Result<RegisterResponse> = runCatching {
        api.register(request)
    }

    suspend fun confirm(email: String, code: String): Result<GenericResponse> = runCatching {
        api.confirm(email, ConfirmRequest(code))
    }

    suspend fun logout(): Result<GenericResponse> = runCatching {
        api.logout()
    }
}

package com.example.echowithin.presentation.screens

import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.Card
import androidx.compose.material3.CardDefaults
import androidx.compose.material3.ExperimentalMaterial3Api
import androidx.compose.material3.FloatingActionButton
import androidx.compose.material3.HorizontalDivider
import androidx.compose.material3.IconButton
import androidx.compose.material3.LinearProgressIndicator
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Scaffold
import androidx.compose.material3.Text
import androidx.compose.material3.TopAppBar
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import com.example.echowithin.data.model.AppNote
import com.example.echowithin.presentation.components.EchoWithinTopBarTitle

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HomeScreen(
    notes: List<AppNote>,
    isLoading: Boolean,
    error: String?,
    onNoteClick: (String) -> Unit,
    onNewNoteClick: () -> Unit,
    onSearchClick: () -> Unit,
    onRetryClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    Scaffold(
        topBar = {
            TopAppBar(
                title = { EchoWithinTopBarTitle() },
                actions = {
                    IconButton(onClick = onSearchClick) {
                        Text("Search")
                    }
                    IconButton(onClick = { }) {
                        Text("More")
                    }
                }
            )
        },
        floatingActionButton = {
            FloatingActionButton(onClick = onNewNoteClick) {
                Text("+")
            }
        }
    ) { innerPadding ->
        when {
            isLoading -> {
                Column(
                    modifier = modifier
                        .fillMaxSize()
                        .padding(innerPadding)
                        .padding(24.dp),
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Text("Loading notes...", style = MaterialTheme.typography.titleMedium)
                    LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
                }
            }

            error != null -> {
                Column(
                    modifier = modifier
                        .fillMaxSize()
                        .padding(innerPadding)
                        .padding(24.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Text("Could not load notes", style = MaterialTheme.typography.titleLarge)
                    Text(error, style = MaterialTheme.typography.bodyMedium)
                    Text(
                        "Retry",
                        color = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.clickable(onClick = onRetryClick)
                    )
                }
            }

            notes.isEmpty() -> {
            Column(
                modifier = modifier
                    .fillMaxSize()
                    .padding(innerPadding)
                    .padding(24.dp),
                verticalArrangement = Arrangement.Center
            ) {
                Text("No notes yet", style = MaterialTheme.typography.titleLarge)
                Text("Tap + to create your first note.", style = MaterialTheme.typography.bodyMedium)
            }
            }

            else -> {
            LazyColumn(
                modifier = modifier
                    .fillMaxSize()
                    .padding(innerPadding)
                    .padding(horizontal = 16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                items(notes) { note ->
                    NoteCard(note = note, onClick = { onNoteClick(note.id) })
                }
            }
            }
        }
    }
}

@Composable
fun NoteCard(note: AppNote, onClick: () -> Unit) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
    ) {
        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
            Text(text = note.title, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold)
            Text(text = note.content.replace("\n", " ").take(180), style = MaterialTheme.typography.bodyMedium)
            if (note.tags.isNotEmpty()) {
                HorizontalDivider()
                Text(text = note.tags.joinToString(prefix = "#", separator = " #"), style = MaterialTheme.typography.labelSmall)
            }
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
                Text(text = note.updatedAt.take(19), style = MaterialTheme.typography.labelSmall)
            }
        }
    }
}

